get_price_display_settings.code:
const response = await client.priceDisplaySettings.getPriceDisplaySettings();
const settings = response.map.price_display_settings;
console.log(settings.order_item.price_including_tax.enabled);
console.log(settings.order_summary.payment_surcharge.enabled);

patch_price_display_settings.code:
const response = await client.priceDisplaySettings.patchPriceDisplaySettings({
    price_display_settings: {
        order_item: {price_including_tax: {enabled: true, customize: false}},
        order_summary: {payment_surcharge: {enabled: true, customize: false}},
    },
});
const settings = response.map.price_display_settings;
console.log(settings.order_item.price_including_tax.enabled);
console.log(settings.order_summary.payment_surcharge.enabled);

get_price_display_settings_section.code:
const response = await client.priceDisplaySettings.getPriceDisplaySettingsSection('order_item');
const orderItem = response.map.order_item;
console.log(orderItem.price_including_tax.enabled, orderItem.price_including_discount.enabled);
